problem:
Problem description
- There is a single planning horizon $$\tau$$ in which production is planned.
- A finite set of products $$\mathcal P$$ must be manufactured, and every unit must pass through two sequential processing stages $$\mathcal S=\{A,B\}$$.
- Stage $$A$$ is performed on a stage-specific machine set $$\mathcal M_A$$, and stage $$B$$ is performed on a stage-specific machine set $$\mathcal M_B$$.
- Product-and-machine feasibility is part of the input through a binary compatibility parameter $$\delta_{p,s,m}$$, where $$\delta_{p,s,m}=1$$ means product $$p$$ may be processed on machine $$m$$ at stage $$s$$, and $$\delta_{p,s,m}=0$$ means that combination is not allowed.
- For each feasible product-stage-machine combination, the input provides a processing time per unit $$t_{p,s,m}$$ measured in machine-hours per piece.
- Each machine-stage combination has a limited available capacity $$H_{s,m}$$ measured in hours within the planning horizon $$\tau$$.
- Each machine-stage combination has a processing cost rate $$c_{s,m}$$ measured in cost per machine-hour.
- Each product has a raw material cost $$r_p$$ per unit and a selling price $$u_p$$ per unit.
- The planning decision is to choose how many units of each product to produce and how to distribute those units across the eligible machines at each stage.
- Every manufactured unit must be processed at stage $$A$$ first and then at stage $$B$$, and the quantity processed through both stages must remain consistent for each product.
- The objective is to maximize total profit over the planning horizon $$\tau$$, where profit is the sales revenue from finished units minus raw material expense and machine processing expense.
- Business requirements:
  - Only compatible product-stage-machine combinations may receive production.
  - No unit may skip either processing stage.
  - The total time used on any machine must not exceed its available hours.
  - All planned quantities must be nonnegative, and if the operating setting requires discrete pieces, quantities must be whole numbers.
  - If an external demand limit $$d_p$$ is supplied for product $$p$$, then the number of units sold for that product must not exceed $$d_p$$; otherwise sales are treated as unconstrained by demand.
- A solution is represented by:
  - $$x_{p,s,m}$$: the number of units of product $$p$$ assigned to machine $$m$$ at stage $$s$$.
  - $$q_p$$: the total finished quantity of product $$p$$ available for sale.
  - $$\Pi^\star$$: the optimal total profit achieved by the production plan.

Input Format
{
  "planning_horizon": "$$\\tau$$",
  "products": {
    "set": "$$\\mathcal P$$",
    "cardinality": "$$P$$"
  },
  "stages": {
    "set": "$$\\mathcal S=\\{A,B\\}$$",
    "cardinality": "$$S=2$$"
  },
  "machines": {
    "stage_A": "$$\\mathcal M_A$$",
    "stage_B": "$$\\mathcal M_B$$"
  },
  "compatibility": {
    "meaning": "$$\\delta_{p,s,m}\\in\\{0,1\\}$$ indicates whether product $$p$$ can be processed on machine $$m$$ at stage $$s$$",
    "shape": "for each $$s\\in\\mathcal S$$ and $$m\\in\\mathcal M_s$$, a vector over $$p\\in\\mathcal P$$"
  },
  "processing_time_per_unit": {
    "meaning": "$$t_{p,s,m}$$ is the machine-hours required to process one unit of product $$p$$ on machine $$m$$ at stage $$s$$",
    "shape": "for each $$s\\in\\mathcal S$$ and $$m\\in\\mathcal M_s$$, a vector over $$p\\in\\mathcal P$$"
  },
  "machine_capacity_hours": {
    "meaning": "$$H_{s,m}$$ is the available machine time on machine $$m$$ at stage $$s$$ during $$\\tau$$",
    "shape": "for each $$s\\in\\mathcal S$$ and $$m\\in\\mathcal M_s$$"
  },
  "processing_cost_per_hour": {
    "meaning": "$$c_{s,m}$$ is the processing cost rate on machine $$m$$ at stage $$s$$",
    "shape": "for each $$s\\in\\mathcal S$$ and $$m\\in\\mathcal M_s$$"
  },
  "raw_material_cost_per_unit": {
    "meaning": "$$r_p$$ is the raw material cost for one unit of product $$p$$",
    "shape": "for each $$p\\in\\mathcal P$$"
  },
  "unit_sales_price": {
    "meaning": "$$u_p$$ is the sales price for one unit of product $$p$$",
    "shape": "for each $$p\\in\\mathcal P$$"
  },
  "demand_cap": {
    "meaning": "$$d_p$$ is an optional maximum sellable quantity for product $$p$$; if omitted, no demand cap is imposed",
    "shape": "optional vector over $$p\\in\\mathcal P$$"
  }
}

Output Format
{
  "assigned_quantity": {
    "field": "$$x_{p,s,m}$$",
    "dimensions": ["$$p\\in\\mathcal P$$", "$$s\\in\\mathcal S$$", "$$m\\in\\mathcal M_s$$"],
    "meaning": "units of product $$p$$ assigned to machine $$m$$ at stage $$s$$"
  },
  "finished_quantity": {
    "field": "$$q_p$$",
    "dimensions": ["$$p\\in\\mathcal P$$"],
    "meaning": "total finished and saleable units of product $$p$$"
  },
  "objective_value": {
    "field": "$$\\Pi^\\star$$",
    "dimensions": ["scalar"],
    "meaning": "maximum total profit"
  }
}

